var db={'1234AB-12':[{d:'2026-01-05',f:'GFT'},{d:'2026-01-19',f:'PMD'},{d:'2026-02-02',f:'GFT'},{d:'2026-03-09',f:'RST'},{d:'2026-04-13',f:'GFT'}],'1234AB-14':[]};
var q=request.queryStringParameters||{};
function p(n,d){return q[n]?q[n][0]:d;}
var key=p('postcode','')+'-'+p('huisnummer','');
if(!(key in db)){ return {statusCode:404,headers:{'Content-Type':['application/problem+json']},body:JSON.stringify({type:'https://diftar-api.example/problemen/adres-niet-gevonden',title:'Adres niet gevonden',status:404,detail:'Adres '+key+' staat niet in de dataset.'})}; }
var vanaf=p('vanaf',''), tot=p('totEnMet','');
var rows=db[key].filter(function(r){return r.d>=vanaf && r.d<=tot;});
var ps=parseInt(p('pageSize','50')), pg=parseInt(p('page','1'));
var out=rows.slice((pg-1)*ps,pg*ps).map(function(r){return {datumTijd:r.d,fractieCode:r.f};});
return {statusCode:200,headers:{'Content-Type':['application/json'],'API-Version':['1.1.0']},body:JSON.stringify({totaalAantalLedigingen:rows.length,ledigingen:out})};
